import gurobipy as gp
from gurobipy import GRB

try:
    # Get data from pre-defined variable
    num_cities = data["num_cities"]
    costs_dict = data["travel_costs"]

    # Validate data
    if num_cities <= 0:
        raise ValueError("Number of cities must be positive")

    # Build cost matrix c[i][j] for i,j in 1..num_cities
    c = [[0] * (num_cities + 1) for _ in range(num_cities + 1)]

    # Fill cost matrix from dictionary
    for i in range(1, num_cities + 1):
        key = f"from_city_{i}"
        if key not in costs_dict:
            raise KeyError(f"Missing travel costs for {key}")

        cost_list = costs_dict[key]
        if len(cost_list) != num_cities - 1:
            raise ValueError(f"Expected {num_cities-1} costs for {key}, got {len(cost_list)}")

        idx = 0
        for j in range(1, num_cities + 1):
            if j == i:
                c[i][j] = 0
            else:
                c[i][j] = cost_list[idx]
                idx += 1

    # Create model
    m = gp.Model("TSP")
    m.Params.OutputFlag = 0

    # Variables: x[i][j] binary for i != j
    x = {}
    for i in range(1, num_cities + 1):
        for j in range(1, num_cities + 1):
            if i != j:
                x[i, j] = m.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

    # MTZ variables u[i] for i=2..n
    u = {}
    for i in range(2, num_cities + 1):
        u[i] = m.addVar(vtype=GRB.CONTINUOUS, lb=1, ub=num_cities - 1, name=f"u_{i}")

    # Constraints: each city has exactly one incoming and one outgoing edge
    for i in range(1, num_cities + 1):
        m.addConstr(gp.quicksum(x[i, j] for j in range(1, num_cities + 1) if j != i) == 1)
    for j in range(1, num_cities + 1):
        m.addConstr(gp.quicksum(x[i, j] for i in range(1, num_cities + 1) if i != j) == 1)

    # MTZ constraints to eliminate subtours
    for i in range(2, num_cities + 1):
        for j in range(2, num_cities + 1):
            if i != j:
                m.addConstr(u[i] - u[j] + num_cities * x[i, j] <= num_cities - 1)

    # Additional MTZ constraints involving city 1
    for j in range(2, num_cities + 1):
        m.addConstr(-u[j] + num_cities * x[1, j] <= num_cities - 1)

    for i in range(2, num_cities + 1):
        m.addConstr(u[i] + num_cities * x[i, 1] <= num_cities - 1)

    # Objective: minimize total travel cost
    obj = gp.quicksum(c[i][j] * x[i, j] for i in range(1, num_cities + 1) 
                      for j in range(1, num_cities + 1) if i != j)
    m.setObjective(obj, GRB.MINIMIZE)

    # Solve the model
    m.optimize()

    # Check solution status
    if m.status == GRB.OPTIMAL:
        print(f"Minimum total travel cost: {m.objVal}")
    else:
        print(f"No optimal solution found. Status: {m.status}")

except KeyError as e:
    print(f"Data error: {e}")
except ValueError as e:
    print(f"Data validation error: {e}")
except gp.GurobiError as e:
    print(f"Gurobi error: {e}")
except Exception as e:
    print(f"Unexpected error: {e}")
