    for j in range(n):
        if i != j:
            x[i, j] = m.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

# Create MTZ variables for subtour elimination (u_0 is not needed)
u = {}
for i in range(1, n):
