        u[i] = m.addVar(vtype=GRB.CONTINUOUS, lb=1, ub=n-1, name=f"u_{i}")

    # Flow conservation constraints
    for i in range(n):
        m.addConstr(gp.quicksum(x[i, j] for j in range(n) if i != j) == 1, name=f"outflow_{i}")

    for j in range(n):
        m.addConstr(gp.quicksum(x[i, j] for i in range(n) if i != j) == 1, name=f"inflow_{j}")

