import gurobipy as gp
from gurobipy import GRB

# Extract data from pre-defined data structure
num_cities = data["num_cities"]
cost_matrix = data["cost_matrix"]

# Create model
m = gp.Model("TSP")
m.Params.OutputFlag = 0

# Create binary variables for edges
x = {}
for i in range(num_cities):
    for j in range(num_cities):
        if i != j:
            x[i, j] = m.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

# Create MTZ variables for subtour elimination (u_i for i=1..n-1)
u = {}
for i in range(1, num_cities):
    u[i] = m.addVar(vtype=GRB.CONTINUOUS, lb=1, ub=num_cities-1, name=f"u_{i}")

# Objective function: minimize total travel cost
obj = gp.quicksum(cost_matrix[i][j] * x[i, j] for i in range(num_cities) for j in range(num_cities) if i != j)
m.setObjective(obj, GRB.MINIMIZE)

# Degree constraints: each city has exactly one incoming and one outgoing edge
for i in range(num_cities):
    m.addConstr(gp.quicksum(x[i, j] for j in range(num_cities) if i != j) == 1, name=f"out_{i}")
    m.addConstr(gp.quicksum(x[j, i] for j in range(num_cities) if i != j) == 1, name=f"in_{i}")

# MTZ constraints to eliminate subtours
for i in range(1, num_cities):
    for j in range(1, num_cities):
        if i != j:
            m.addConstr(u[i] - u[j] + (num_cities - 1) * x[i, j] <= num_cities - 2, name=f"mtz_{i}_{j}")

# Optimize the model
m.optimize()

# Check if solution was found and print results
if m.status == GRB.OPTIMAL:
    print(f"Minimum total travel cost: {m.objVal}")
else:
    print(f"Optimization failed with status: {m.status}")
