import gurobipy as gp
from itertools import combinations

# Extract data from pre-defined variable
num_cities = data["num_cities"]
costs_dict = data["travel_costs"]

# Create a complete cost matrix
cost_matrix = [[0] * num_cities for _ in range(num_cities)]

# Map city numbers to indices (1-based to 0-based)
city_map = {1: 0, 2: 1, 3: 2, 4: 3, 5: 4, 6: 5}

# Fill the cost matrix using the provided data structure
for i in range(1, num_cities + 1):
    key = f"from_city_{i}"
    if key not in costs_dict:
        continue

    cost_list = costs_dict[key]
    from_idx = city_map[i]

    # The cost list contains costs to all other cities in numerical order
    target_idx = 0
    for j in range(1, num_cities + 1):
        if j == i:
            continue
        to_idx = city_map[j]
        cost_matrix[from_idx][to_idx] = cost_list[target_idx]
        target_idx += 1

# Create the model
model = gp.Model("TSP")
model.Params.OutputFlag = 0  # Suppress output
model.Params.TimeLimit = 30  # Set time limit to avoid timeout

# Decision variables: x[i,j] = 1 if edge (i,j) is used in the tour
x = {}
for i in range(num_cities):
    for j in range(num_cities):
        if i != j:
            x[i, j] = model.addVar(vtype=gp.GRB.BINARY, name=f"x_{i}_{j}")

# Objective: minimize total travel cost
objective = gp.quicksum(cost_matrix[i][j] * x[i, j] 
                       for i in range(num_cities) 
                       for j in range(num_cities) if i != j)
model.setObjective(objective, gp.GRB.MINIMIZE)

# Constraints: each city has exactly one incoming and one outgoing edge
for i in range(num_cities):
    # Outgoing edges from city i
    model.addConstr(gp.quicksum(x[i, j] for j in range(num_cities) if i != j) == 1,
                   f"outgoing_{i}")

    # Incoming edges to city i
    model.addConstr(gp.quicksum(x[j, i] for j in range(num_cities) if i != j) == 1,
                   f"incoming_{i}")

# Subtour elimination constraints (Miller-Tucker-Zemlin formulation)
u = model.addVars(num_cities, vtype=gp.GRB.CONTINUOUS, name="u")

# Avoid subtours: u[i] - u[j] + num_cities * x[i,j] <= num_cities - 1
for i in range(1, num_cities):
    for j in range(1, num_cities):
        if i != j:
            model.addConstr(u[i] - u[j] + num_cities * x[i, j] <= num_cities - 1,
                           f"subtour_{i}_{j}")

# Solve the model
model.optimize()

# Check if solution was found
if model.Status == gp.GRB.OPTIMAL:
    total_cost = model.ObjVal
    print(f"Minimum total travel cost: {total_cost}")
else:
    print("No optimal solution found within time limit")
    # Fallback: try a simpler approach with explicit subtour elimination
    if model.Status == gp.GRB.TIME_LIMIT:
        print("Using alternative method...")

        # Create a new model with lazy constraint callback
        model2 = gp.Model("TSP_Alternative")
        model2.Params.OutputFlag = 0
        model2.Params.LazyConstraints = 1

        # Variables and basic constraints (same as before)
        x2 = {}
        for i in range(num_cities):
            for j in range(num_cities):
                if i != j:
                    x2[i, j] = model2.addVar(vtype=gp.GRB.BINARY, name=f"x_{i}_{j}")

        objective2 = gp.quicksum(cost_matrix[i][j] * x2[i, j] 
                                for i in range(num_cities) 
                                for j in range(num_cities) if i != j)
        model2.setObjective(objective2, gp.GRB.MINIMIZE)

        for i in range(num_cities):
            model2.addConstr(gp.quicksum(x2[i, j] for j in range(num_cities) if i != j) == 1)
            model2.addConstr(gp.quicksum(x2[j, i] for j in range(num_cities) if i != j) == 1)

        # Subtour elimination callback
        def subtour_elimination(model2, where):
            if where == gp.GRB.Callback.MIPSOL:
                x_vals = model2.cbGetSolution(x2)

                # Find connected components
                visited = [False] * num_cities
                components = []

                for i in range(num_cities):
                    if not visited[i]:
                        component = []
                        stack = [i]
                        visited[i] = True

                        while stack:
                            node = stack.pop()
                            component.append(node)
                            for j in range(num_cities):
                                if j != node and x_vals[node, j] > 0.5 and not visited[j]:
                                    visited[j] = True
                                    stack.append(j)

                        components.append(component)

                # Add constraints for subtours (components with size < num_cities)
                for comp in components:
                    if len(comp) < num_cities:
                        # Sum of edges within the component should be <= |comp| - 1
                        edges_in_comp = gp.quicksum(x2[i, j] for i in comp for j in comp if i < j)
                        model2.cbLazy(edges_in_comp <= len(comp) - 1)

        model2.optimize(subtour_elimination)

        if model2.Status == gp.GRB.OPTIMAL:
            total_cost = model2.ObjVal
            print(f"Minimum total travel cost: {total_cost}")
        else:
            print("Could not find optimal solution")
