    # Decision variables: x[i,j] = 1 if edge (i,j) is used in the tour
    x = {}
    for i in range(num_cities):
        for j in range(num_cities):
            if i != j:
                x[i, j] = model.addVar(vtype=gp.GRB.BINARY, name=f"x_{i}_{j}")

    # Objective: minimize total travel cost
    objective = gp.quicksum(cost_matrix[i][j] * x[i, j] 
                           for i in range(num_cities) 
                           for j in range(num_cities) if i != j)
    model.setObjective(objective, gp.GRB.MINIMIZE)

    # Constraints: each city has exactly one incoming and one outgoing edge
    for i in range(num_cities):
        # Outgoing edges from city i
        model.addConstr(gp.quicksum(x[i, j] for j in range(num_cities) if i != j) == 1,
                       f"outgoing_{i}")

        # Incoming edges to city i
        model.addConstr(gp.quicksum(x[j, i] for j in range(num_cities) if i != j) == 1,
                       f"incoming_{i}")

    # Subtour elimination constraints using combinatorial approach
    # Add constraints for all subsets of cities (size 2 to n-1)
    for subset_size in range(2, num_cities):
        for subset in combinations(range(num_cities), subset_size):
            # Sum of edges within the subset should be <= |subset| - 1
            edges_in_subset = gp.quicksum(x[i, j] for i in subset for j in subset if i != j)
            model.addConstr(edges_in_subset <= len(subset) - 1)

    # Solve the model
    model.optimize()

    # Check if solution was found
    if model.Status == gp.GRB.OPTIMAL:
        total_cost = model.ObjVal
        print(f"Minimum total travel cost: {int(total_cost)}")
    elif model.Status == gp.GRB.INFEASIBLE:
        print("Model is infeasible")
    elif model.Status == gp.GRB.UNBOUNDED:
        print("Model is unbounded")
    else:
        print(f"No optimal solution found. Status: {model.Status}")

except KeyError as e:
    print(f"Missing data key: {e}")
except ValueError as e:
    print(f"Data validation error: {e}")
except TypeError as e:
    print(f"Type error: {e}")
except gp.GurobiError as e:
    print(f"Gurobi error: {e}")
except Exception as e:
    print(f"Unexpected error: {e}")
