import gurobipy as gp

# Extract data from predefined variable
num_stations = data["num_stations"]
source = data["source_station"]
dest = data["destination_station"]
caps_dict = data["pipeline_capacities"]

# Build capacity matrix: cap[i][j] for i->j
cap = [[0] * num_stations for _ in range(num_stations)]

for i in range(num_stations):
    key = f"from_{i}"
    if key not in caps_dict:
        continue
    capacities = caps_dict[key]
    destinations = [j for j in range(num_stations) if j != i]
    for idx, j in enumerate(destinations):
        if idx < len(capacities):
            cap[i][j] = capacities[idx]

# Create model
m = gp.Model("max_flow")
m.Params.OutputFlag = 0

# Flow variables: x[i][j]
x = {}
for i in range(num_stations):
    for j in range(num_stations):
        if cap[i][j] > 0:
            x[i, j] = m.addVar(lb=0, ub=cap[i][j], name=f"x_{i}_{j}")
        else:
            x[i, j] = m.addVar(lb=0, ub=0, name=f"x_{i}_{j}")

# Create flow variable F
F = m.addVar(name="F")

# Flow conservation constraints
for i in range(num_stations):
    outflow = gp.quicksum(x[i, j] for j in range(num_stations))
    inflow = gp.quicksum(x[j, i] for j in range(num_stations))

    if i == source:
        m.addConstr(outflow - inflow == F, f"source_flow")
    elif i == dest:
        m.addConstr(outflow - inflow == -F, f"sink_flow")
    else:
        m.addConstr(outflow - inflow == 0, f"node_{i}_balance")

# Objective: maximize F
m.setObjective(F, gp.GRB.MAXIMIZE)

# Solve
m.optimize()

if m.Status == gp.GRB.OPTIMAL:
    print(f"Maximum flow: {F.X}")
else:
    print("No optimal solution found")
