            routes.append((3, 4, costs_dict["from_4"]["to_5"]))

    # Decision variables: x[i,j] for each allowed route
    x = {}
    for (i, j, cost) in routes:
        x[i, j] = m.addVar(vtype=GRB.INTEGER, lb=0, name=f"x_{i+1}_{j+1}")

    # Supply constraints
    for i in range(num_locations):
        if supply[i] > 0:
            outgoing = gp.quicksum(x.get((i, j), 0) for j in range(num_locations) if (i, j) in x)
            m.addConstr(outgoing <= supply[i], name=f"supply_{i+1}")

    # Demand constraints
    for j in range(num_locations):
        if demand[j] > 0:
            incoming = gp.quicksum(x.get((i, j), 0) for i in range(num_locations) if (i, j) in x)
            m.addConstr(incoming >= demand[j], name=f"demand_{j+1}")

    # Objective: minimize total cost
    total_cost = gp.quicksum(cost * x[i, j] for (i, j, cost) in routes)
    m.setObjective(total_cost, GRB.MINIMIZE)

    # Solve
    m.optimize()

    if m.status == GRB.OPTIMAL:
        print(int(round(m.objVal)))
    else:
        print("No optimal solution found")

except Exception as e:
    print(f"Error: {e}")
