import gurobipy as gp

try:
    # Extract data with error handling
    edge_capacities = data.get("edge_capacities", [])
    n_nodes = data.get("number_of_nodes", 0)
    start = data.get("start_node", 1)
    end = data.get("end_node", 4)

    if n_nodes <= 0 or not edge_capacities:
        print(0)
        exit()

    m = gp.Model()
    m.Params.OutputFlag = 0

    # Create flow variables for each edge
    flow_vars = {}
    for edge in edge_capacities:
        i = edge.get("from")
        j = edge.get("to")
        cap = edge.get("capacity")
        if i is not None and j is not None and cap is not None:
            flow_vars[(i, j)] = m.addVar(lb=0, ub=cap, name=f"f_{i}_{j}")

    # Flow conservation constraints for all nodes except start and end
    for node in range(1, n_nodes + 1):
        if node == start or node == end:
            continue

        inflow = gp.quicksum(
            flow_vars.get((i, node), 0) for i in range(1, n_nodes + 1)
        )
        outflow = gp.quicksum(
            flow_vars.get((node, j), 0) for j in range(1, n_nodes + 1)
        )
        m.addConstr(inflow == outflow, name=f"conservation_{node}")

    # Objective: maximize flow out of start node
    outflow_start = gp.quicksum(
        flow_vars.get((start, j), 0) for j in range(1, n_nodes + 1)
    )
    m.setObjective(outflow_start, gp.GRB.MAXIMIZE)

    m.optimize()

    if m.Status == gp.GRB.OPTIMAL:
        print(int(round(m.ObjVal)))
    else:
        print(0)

except Exception as e:
